import csv
import math
from collections import Counter

invoices = []
with open("/app/dataset/invoices.csv", mode="r") as f:
    reader = csv.DictReader(f)
    for row in reader:
        invoices.append({
            "seller_id": int(row["seller_id"]),
            "gross_amount": float(row["gross_amount"])
        })

benford_probs = {d: math.log10(1 + 1.0/d) for d in range(1, 10)}

for s_id in [2029, 4612, 6453, 8382]:
    s_invs = [inv for inv in invoices if inv["seller_id"] == s_id]
    digits = []
    for inv in s_invs:
        val = inv["gross_amount"]
        if val > 0:
            s_val = str(val).lstrip("0.")
            if s_val:
                digits.append(int(s_val[0]))
    counts = Counter(digits)
    total = len(digits)
    ssd = 0.0
    for d in range(1, 10):
        observed = counts[d] / total if total > 0 else 0
        expected = benford_probs[d]
        ssd += (observed - expected) ** 2
    print(f"Seller {s_id}: N={len(s_invs)}, SSD={ssd:.6f}, Counts={dict(sorted(counts.items()))}")

